interface TreeData {
    id: string;
    subList?: TreeData[];
    children?: TreeData[];
    [key: string]: any;
}
declare type Predicate<T> = (item: T) => boolean;
/**
 * Finds a single element in a nested data structure based on a target key and an optional condition.
 * @param data
 * @param targetKey
 * @param condition
 * @returns
 */
declare function findRecursive<T extends TreeData>(data: T | T[], targetKey: keyof T, condition?: Predicate<T>): T | null;
/**
 * Finds all elements in a nested data structure based on a target key and an optional condition.
 * @param data
 * @param targetKey
 * @param condition
 * @returns
 */
declare function findAllRecursive<T extends TreeData>(data: T | T[], targetKey: keyof T, condition?: Predicate<T>): T[];
export { findRecursive, findAllRecursive };
